/bin/zsh -lc "MPLCONFIGDIR=/tmp/brainx-mpl JAX_PLATFORMS=cpu python - <<'PY'
import brainpy, brainstate, braintools, brainunit as u

def count(current, steps=9):
  with brainstate.environ.context(dt=1*u.ms):
    n=brainpy.state.LIFRef(1,R=100*u.Mohm,tau=15*u.ms,tau_ref=3*u.ms,V_rest=-65*u.mV,V_th=-50*u.mV,V_reset=-65*u.mV,V_initializer=braintools.init.Constant(-65*u.mV))
    brainstate.nn.init_all_states(n)
    ts=u.math.arange(0*u.ms,steps*u.ms,1*u.ms)
    def step(t):
      with brainstate.environ.context(t=t): return n(current)
    return int(brainstate.transform.for_loop(step, ts).sum())
for current in [0.25,0.35,0.45,0.55,0.7,0.9]:
  print(current, count(current*u.nA))
PY"

